"""Research endpoints, mounted at ``/api/research``.

``POST /ask`` picks the collections for the requested jurisdiction, runs a hybrid search
over ``aurum.corpus`` in each, and either cites supporting chunks or abstains — the
"grounded or silent" principle (docs/ARCHITECTURE.md). The answer text itself is generated by
``aurum.llm.structured.generate_text`` when a provider is reachable; on ANY provider
error (timeout, connection refused, bad response) it falls back to an **extractive**
answer built directly from the top cited chunks, so the endpoint works with no LLM
running at all. Every answer — generated or extractive — ends with a
not-advice/verify-with-a-professional line in the requested language.

``POST /ingest`` and ``GET /collections`` are thin wrappers over ``aurum.corpus``.
"""

from __future__ import annotations

import re
import uuid
from pathlib import Path
from typing import Any, Literal

import httpx
from fastapi import APIRouter, File, Form, Header, HTTPException, Request, UploadFile
from pydantic import BaseModel, Field

from ..core import audit
from ..core.netguard import FetchBlocked, FetchTooLarge, fetch_public_url
from ..corpus import cite as cite_mod
from ..corpus import ingest as ingest_mod
from ..corpus import refs as refs_mod
from ..corpus.search import search as corpus_search
from ..corpus.store import CorpusError, open_store
from ..llm.exceptions import CloudNotAllowed
from ..llm.structured import generate_text

router = APIRouter(tags=["research"])

Jurisdiction = Literal["MX", "US", "both"]
Lang = Literal["es", "en"]

#: Which corpus collections back which jurisdiction.
COLLECTIONS_BY_JURISDICTION: dict[str, list[str]] = {
    "MX": ["mx-law", "guidance"],
    "US": ["us-law", "guidance"],
    "both": ["mx-law", "us-law", "guidance"],
}

#: Collection ids are path components on disk (``corpus_sources/<id>``) and DB keys: public ids are
#: ``[a-z0-9][a-z0-9_-]{0,63}``, private ones ``ws:<workspace id>`` (no path traversal).
COLLECTION_RE = re.compile(r"^(ws:[a-z0-9][a-z0-9-]{1,40}|[a-z0-9][a-z0-9_-]{0,63})$")

#: A supporting chunk must come from one of these to ground an *asserted* answer —
#: a "blog"/"professional" hit alone is not enough to stop the endpoint abstaining.
TRUSTED_TIERS = {"primary", "official_guidance"}

NOT_ADVICE = {
    "es": "Esto no es asesoría fiscal ni legal — verifica con un Contador Público (CPA/Contador) autorizado antes de actuar.",
    "en": "This is not tax or legal advice — verify with a licensed CPA/Contador before acting.",
}

ABSTAIN_TEXT = {
    "es": "No encontré suficiente respaldo en el corpus para responder con confianza. {reason}",
    "en": "I could not find enough support in the corpus to answer confidently. {reason}",
}


class AskRequest(BaseModel):
    question: str
    jurisdiction: Jurisdiction = "MX"
    lang: Lang = "es"
    workspace: str | None = None
    as_of: str | None = None


class AskResponse(BaseModel):
    answer: str
    citations: list[dict[str, Any]] = Field(default_factory=list)
    confidence: float
    abstained: bool


def _collections_for(jurisdiction: str, workspace: str | None = None) -> list[str]:
    """Public collections for the jurisdiction, plus the caller's own ``ws:{id}`` collection.

    Private per-workspace collections are never searched unless the
    request itself names that workspace — either the ``workspace`` field of ``/ask`` or the
    ``X-Aurum-Workspace`` header on ``/ingest``/``/collections``. This is the whole
    permission filter: a workspace's private material is invisible to every other workspace
    and to anonymous requests.
    """
    base = list(COLLECTIONS_BY_JURISDICTION.get(jurisdiction, COLLECTIONS_BY_JURISDICTION["MX"]))
    if workspace:
        base.append(f"ws:{workspace}")
    return base


def _is_private_collection(collection_id: str) -> bool:
    return collection_id.startswith("ws:")


def _private_owner(collection_id: str) -> str | None:
    return collection_id[len("ws:"):] if _is_private_collection(collection_id) else None


def _gather_hits(
    store, collections: list[str], question: str, k: int = 8, *, as_of: str | None = None
) -> list[dict[str, Any]]:
    hits: list[dict[str, Any]] = []
    for collection_id in collections:
        found = corpus_search(store, collection_id, question, k=k, as_of=as_of)
        assert isinstance(found, list)
        hits.extend(found)
    hits.sort(key=lambda c: (-float(c.get("score") or 0.0), -float(c.get("support") or 0.0)))
    return hits


def _extractive_answer(question: str, citations: list[dict[str, Any]], lang: str) -> str:
    """No LLM available (or it errored): stitch the top excerpts into a plain answer.

    Deliberately unglamorous — a numbered list of what the corpus actually says, each line
    naming its own citation, so the caller can still trust it without any generation step.
    """
    lead = {
        "es": "Con base en el corpus (sin generación por IA, respuesta extractiva):",
        "en": "Based on the corpus (no AI generation, extractive answer):",
    }[lang]
    lines = [lead]
    for citation in citations:
        label = citation["law"]
        if citation.get("article"):
            label += f" art. {citation['article']}"
        excerpt = citation.get("excerpt") or ""
        lines.append(f"- ({label}) {excerpt}")
    return "\n".join(lines)


def _prompt(question: str, citations: list[dict[str, Any]], lang: str) -> str:
    sources = []
    for i, citation in enumerate(citations, start=1):
        label = citation["law"]
        if citation.get("article"):
            label += f" art. {citation['article']}"
        sources.append(f"[{i}] {label}: {citation.get('excerpt') or ''}")
    joined = "\n".join(sources)
    if lang == "es":
        return (
            "Eres un asistente de investigación fiscal/legal. Responde la pregunta del usuario "
            "USANDO SOLO la información de las fuentes citadas abajo. Cita cada afirmación con "
            "su número de fuente entre corchetes, p. ej. [1]. Si las fuentes no cubren algo, dilo "
            "explícitamente en vez de inventarlo. No des asesoría personalizada, solo explica la ley.\n\n"
            f"Pregunta: {question}\n\nFuentes:\n{joined}\n\nRespuesta:"
        )
    return (
        "You are a tax/legal research assistant. Answer the user's question USING ONLY the "
        "information in the sources below. Cite every claim with its bracketed source number, "
        "e.g. [1]. If the sources do not cover something, say so explicitly rather than "
        "inventing it. Do not give personalized advice, only explain the law.\n\n"
        f"Question: {question}\n\nSources:\n{joined}\n\nAnswer:"
    )


@router.post("/ask")
def ask(body: AskRequest) -> dict:
    question = (body.question or "").strip()
    lang = body.lang
    if not question:
        raise HTTPException(400, "question is required")

    store = open_store()
    try:
        collections = _collections_for(body.jurisdiction, body.workspace)
        hits = _gather_hits(store, collections, question, as_of=body.as_of)
        threshold = cite_mod.min_score_default()
        supported = [c for c in hits if float(c.get("support") or 0.0) >= threshold]
        trusted = [c for c in supported if str(c.get("trust_tier") or "") in TRUSTED_TIERS]

        if not supported:
            reason = "no corpus material matched this question" if not hits else (
                f"best corpus match supports only "
                f"{max(float(c.get('support') or 0.0) for c in hits):.2f} of the question's content "
                f"words (threshold {threshold:.2f})"
            )
            answer = ABSTAIN_TEXT[lang].format(reason=reason) + " " + NOT_ADVICE[lang]
            result = {"answer": answer, "citations": [], "confidence": 0.0, "abstained": True}
        elif not trusted:
            reason = (
                "matching corpus material exists but none of it is a primary statute or official "
                "guidance source (trust_tier)"
                if lang == "en"
                else "hay material que coincide pero ninguno es una fuente primaria u oficial (trust_tier)"
            )
            answer = ABSTAIN_TEXT[lang].format(reason=reason) + " " + NOT_ADVICE[lang]
            result = {"answer": answer, "citations": [], "confidence": 0.0, "abstained": True}
        else:
            citations = [cite_mod.to_citation(c, question, store=store) for c in trusted[:5]]
            confidence = round(sum(c["support"] for c in citations) / len(citations), 4)
            try:
                text, _meta = generate_text(
                    _prompt(question, citations, lang),
                    role="research",
                    contains_raw_documents=False,
                )
                answer = text.strip()
            except (CloudNotAllowed, httpx.HTTPError, ConnectionError, TimeoutError, OSError, ValueError) as exc:
                answer = _extractive_answer(question, citations, lang) + f"\n\n({exc.__class__.__name__}: llm unavailable, extractive fallback)"
            answer = answer.rstrip() + "\n\n" + NOT_ADVICE[lang]
            result = {"answer": answer, "citations": citations, "confidence": confidence, "abstained": False}
    finally:
        store.close()

    audit.record(
        body.workspace,
        "research.ask",
        {"question": question, "jurisdiction": body.jurisdiction, "lang": lang},
        {"abstained": result["abstained"], "confidence": result["confidence"], "citations": len(result["citations"])},
    )
    return result


@router.post("/eval")
def eval_endpoint() -> dict:
    """Run ``evalset.yaml`` against the corpus. Scores retrieval, not generation."""
    from . import eval as eval_mod

    store = open_store()
    try:
        return eval_mod.run_eval(store)
    finally:
        store.close()


@router.get("/refs")
def refs(law: str, article: str) -> dict:
    """The light cross-reference graph for one (law, article).

    ``cites``: what chunks tagged with this law/article themselves mention.
    ``cited_by``: what other law/article chunks mention this one.
    """
    store = open_store()
    try:
        return {
            "law": law,
            "article": article,
            "cites": refs_mod.cites(store, law, article),
            "cited_by": refs_mod.cited_by(store, law, article),
        }
    finally:
        store.close()


@router.get("/collections")
def collections(x_aurum_workspace: str | None = Header(None)) -> dict:
    """Public collections, plus the caller's own ``ws:{id}`` private collection if named."""
    store = open_store()
    try:
        rows = store.query(
            "SELECT s.collection_id AS collection_id, COUNT(DISTINCT s.source_id) AS sources, "
            "COUNT(c.chunk_id) AS chunks FROM sources s LEFT JOIN chunks c ON c.source_id = s.source_id "
            "GROUP BY s.collection_id ORDER BY s.collection_id"
        )
        visible = []
        for row in rows:
            row = dict(row)
            owner = _private_owner(row["collection_id"])
            if owner is not None and owner != x_aurum_workspace:
                continue
            visible.append(row)
        return {"collections": visible}
    finally:
        store.close()


def _fetch_transport() -> httpx.BaseTransport | None:
    """The seam tests replace with an ``httpx.MockTransport``; ``None`` = httpx's real transport."""
    return None


@router.post("/ingest")
async def ingest(
    request: Request,
    file: UploadFile | None = File(None),  # noqa: B008
    collection: str | None = Form(None),  # noqa: B008
    trust_tier: str = Form("primary"),  # noqa: B008
    law: str = Form(""),  # noqa: B008
    jurisdiction: str = Form(""),  # noqa: B008
    doc_type: str = Form(""),  # noqa: B008
    effective_from: str | None = Form(None),  # noqa: B008
    url: str | None = Form(None),  # noqa: B008
    x_aurum_workspace: str | None = Header(None),
) -> dict:
    """Ingest a document into the corpus. Multipart ``file`` upload, or JSON ``{"url": ...}``.

    JSON is detected from the request's content-type so both shapes hit this one route.
    """
    content_type = request.headers.get("content-type", "")
    if content_type.startswith("application/json"):
        payload = await request.json()
        collection = payload.get("collection") or collection
        trust_tier = payload.get("trust_tier") or trust_tier
        law = payload.get("law") or law
        jurisdiction = payload.get("jurisdiction") or jurisdiction
        doc_type = payload.get("doc_type") or doc_type
        effective_from = payload.get("effective_from") or effective_from
        url = payload.get("url") or url

    if not collection:
        raise HTTPException(400, "collection is required")
    if not COLLECTION_RE.match(collection):
        raise HTTPException(400, "invalid collection id")
    owner = _private_owner(collection)
    if owner is not None and owner != x_aurum_workspace:
        raise HTTPException(403, "private collection: request must name its own workspace")

    store = open_store()
    try:
        if file is not None:
            # Validate the type BEFORE any byte lands on disk; the client filename is never a path.
            suffix = Path(file.filename or "").suffix.lower()
            if not suffix:
                raise HTTPException(400, "file needs an extension (supported: " + ", ".join(ingest_mod.SUPPORTED_KINDS) + ")")
            try:
                ingest_mod.kind_for(Path("x" + suffix))
            except (CorpusError, NotImplementedError) as exc:
                raise HTTPException(400, str(exc)) from exc
            # ":" (as in "ws:{id}") is invalid in a Windows path component; the on-disk dir
            # name is cosmetic only — the real collection_id stays intact in the DB row.
            sources_root = (store.settings.data_dir / "corpus_sources").resolve()
            dest_dir = (sources_root / collection.replace(":", "_")).resolve()
            if not dest_dir.is_relative_to(sources_root):
                raise HTTPException(400, "invalid collection id")
            dest_dir.mkdir(parents=True, exist_ok=True)
            dest = dest_dir / f"{uuid.uuid4().hex}{suffix}"
            title = Path(file.filename or f"upload{suffix}").name[:200]
            dest.write_bytes(await file.read())
            try:
                result = ingest_mod.ingest_file(
                    store,
                    collection,
                    dest,
                    title=title,
                    jurisdiction=jurisdiction,
                    doc_type=doc_type,
                    law=law,
                    url=url or "",
                    trust_tier=trust_tier,
                    effective_from=effective_from,
                )
            except (CorpusError, NotImplementedError) as exc:
                dest.unlink(missing_ok=True)
                raise HTTPException(400, str(exc)) from exc
            except Exception:
                dest.unlink(missing_ok=True)
                raise
        elif url:
            try:
                resp = fetch_public_url(
                    url, timeout=20.0, headers={"User-Agent": "aurum-research/0.1"}, transport=_fetch_transport()
                )
                resp.raise_for_status()
            except FetchBlocked as exc:
                raise HTTPException(400, "url_not_allowed") from exc
            except FetchTooLarge as exc:
                raise HTTPException(400, "fetch_too_large") from exc
            except httpx.HTTPError as exc:
                raise HTTPException(502, f"could not fetch {url}: {exc}") from exc
            content_kind = "html" if "html" in resp.headers.get("content-type", "") else "txt"
            try:
                result = ingest_mod.ingest_text(
                    store,
                    collection,
                    resp.text,
                    title=url,
                    kind=content_kind,
                    path_or_url=url,
                    jurisdiction=jurisdiction,
                    doc_type=doc_type,
                    law=law,
                    url=url,
                    trust_tier=trust_tier,
                    effective_from=effective_from,
                )
            except CorpusError as exc:
                raise HTTPException(400, str(exc)) from exc
        else:
            raise HTTPException(400, "provide either a multipart 'file' or a JSON/form 'url'")
    finally:
        store.close()
    return result
